#include <algorithm>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;

class Item {
public:
    Item(int id, const string& name) : id(id), name(name) {}
    int id;
    string name;
    bool out = false;
};

class Library {
public:
    void add(int id, const string& name) { shelf.push_back(make_unique<Item>(id, name)); }

    bool borrow(int id) {
        Item* it = find(id);
        if (!it || it->out) return false;
        it->out = true;
        return true;
    }

    int outCount() const {
        return count_if(shelf.begin(), shelf.end(), [](const unique_ptr<Item>& p) { return p->out; });
    }

private:
    Item* find(int id) {
        for (auto& it : shelf) if (it->id == id) return it.get();
        return nullptr;
    }
    vector<unique_ptr<Item>> shelf;
};

int main() {
    Library lib;
    lib.add(1, "鱼干小百科");
    lib.add({bid}, "猫粮月报");

    cout << (lib.borrow({bid}) ? "办好了" : "办不了") << " " << {bid} << endl;
    cout << (lib.borrow({bid}) ? "办好了" : "办不了") << " " << {bid} << endl;
    cout << "借出去 " << lib.outCount() << " 件" << endl;
    return 0;
}
